@use '../../../styles/variables/colors' as *;

// Item 组容器
.group {
	display: flex;
	flex-direction: column;
}

// 条目分隔线
.separator {
	flex-shrink: 0;
	height: 1px;
	width: 100%;
	background-color: var(--tile-item-line, $border);
}

// 条目根容器
.item {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	border-radius: var(--tile-item-radius, $radius);
	border: 1px solid transparent;
	font-size: $text-sm;
	transition: background-color $transition-fast;
	outline: none;

	&:focus-visible {
		border-color: $ring;
		box-shadow: var(--tile-item-focus-shadow, 0 0 0 3px color-mix(in srgb, $ring 50%, transparent));
	}

	a {
		transition: background-color $transition-fast;
	}

	a:hover {
		background-color: color-mix(in srgb, $accent 50%, transparent);
	}

	// 样式变体
	&.variantDefault {
		background-color: transparent;
	}

	&.variantOutline {
		border-color: var(--tile-item-line, $border);
	}

	&.variantMuted {
		background-color: var(--tile-item-muted-background, color-mix(in srgb, $muted 50%, transparent));
	}

	// 尺寸变体
	&.sizeDefault {
		gap: $spacing-4;
		padding: var(--tile-item-padding, $spacing-4);
	}

	&.sizeSm {
		gap: $spacing-2_5;
		padding: var(--tile-item-sm-padding, $spacing-3 $spacing-4);
	}
}

// 媒体区
.media {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	gap: $spacing-2;

	svg {
		pointer-events: none;
		flex-shrink: 0;
		width: $spacing-4;
		height: $spacing-4;
	}

	// 变体
	&.variantDefault {
		background-color: transparent;
	}

	&.variantIcon {
		width: $spacing-8;
		height: $spacing-8;
		border-radius: $radius-sm;
		border: 1px solid $border;
		background-color: var(--tile-item-media-background, $muted);

		svg {
			width: $spacing-4;
			height: $spacing-4;
		}
	}

	&.variantImage {
		width: $spacing-10;
		height: $spacing-10;
		overflow: hidden;
		border-radius: $radius-sm;

		img {
			width: 100%;
			height: 100%;
			object-fit: cover;
		}
	}
}

// 内容区
.content {
	display: flex;
	flex: 1;
	flex-direction: column;
	gap: $spacing-1;
}

// 相邻的第二个内容区不参与 flex 拉伸
.content + .content {
	flex: none;
}

// 标题
.title {
	display: flex;
	width: fit-content;
	align-items: center;
	gap: $spacing-2;
	font-size: $text-sm;
	line-height: $leading-tight;
	font-weight: $font-medium;
}

// 描述
.description {
	display: -webkit-box;
	-webkit-box-orient: vertical;
	-webkit-line-clamp: 2;
	overflow: hidden;
	font-size: $text-sm;
	line-height: $leading-normal;
	font-weight: $font-normal;
	color: var(--tile-item-description-color, $muted-foreground);
	text-wrap: balance;

	a {
		text-decoration: underline;
		text-underline-offset: 4px;
	}

	a:hover {
		color: $primary;
	}
}

// 操作区
.actions {
	display: flex;
	align-items: center;
	gap: $spacing-2;
}

// 头部 / 底部
.header,
.footer {
	display: flex;
	flex-basis: 100%;
	align-items: center;
	justify-content: space-between;
	gap: $spacing-2;
}
